"""
Star Package Management Engine
Authoritative Reference: STAR_RUNTIME.md (Section 5)
"""

import os
import hashlib
import tarfile
import json
from typing import Dict, List, Optional, Any, Tuple
from dataclasses import dataclass, field


@dataclass
class Dependency:
    name: str
    version: str
    source: str
    checksum: Optional[str] = None


@dataclass
class Lockfile:
    version: int = 1
    packages: List[Dependency] = field(default_factory=list)

    def to_toml(self) -> str:
        lines = [
            "# Auto-generated by Star Package Manager. Do not edit manually.",
            f"lockfile_version = {self.version}",
            ""
        ]
        for p in self.packages:
            lines.append("[[package]]")
            lines.append(f'name = "{p.name}"')
            lines.append(f'version = "{p.version}"')
            lines.append(f'source = "{p.source}"')
            if p.checksum:
                lines.append(f'checksum = "{p.checksum}"')
            lines.append("")
        return "\n".join(lines)


@dataclass
class ProjectManifest:
    name: str
    version: str = "1.0.0"
    target: str = "universal"
    description: str = "A Star Application"
    dependencies: Dict[str, str] = field(default_factory=dict)


PackageLock = Lockfile


def match_version_constraint(version: str, constraint: str) -> bool:
    constraint = constraint.strip()
    if constraint in ("*", "latest", ""):
        return True

    def _parse_v(v_str: str) -> Tuple[int, int, int]:
        parts = [int(p) if p.isdigit() else 0 for p in v_str.replace("v", "").split(".")]
        while len(parts) < 3:
            parts.append(0)
        return (parts[0], parts[1], parts[2])

    target = _parse_v(version)

    if constraint.startswith("^"):
        base = _parse_v(constraint[1:])
        if target[0] != base[0]:
            return False
        return target >= base

    if constraint.startswith("~"):
        base = _parse_v(constraint[1:])
        if target[0] != base[0] or target[1] != base[1]:
            return False
        return target >= base

    if constraint.startswith(">="):
        base = _parse_v(constraint[2:])
        return target >= base

    if constraint.startswith(">"):
        base = _parse_v(constraint[1:])
        return target > base

    if constraint.startswith("<="):
        base = _parse_v(constraint[2:])
        return target <= base

    if constraint.startswith("<"):
        base = _parse_v(constraint[1:])
        return target < base

    return _parse_v(constraint) == target


class PackageManager:
    def __init__(self, project_dir: Optional[str] = None):
        self.project_dir = os.path.abspath(project_dir or os.getcwd())
        self.toml_path = os.path.join(self.project_dir, "star.toml")
        self.lock_path = os.path.join(self.project_dir, "star.lock")
        self.packages_dir = os.path.join(self.project_dir, "packages")

    def load_manifest(self) -> Optional[ProjectManifest]:
        if not os.path.exists(self.toml_path):
            return None
        name = "app"
        version = "1.0.0"
        target = "universal"
        desc = "A Star Application"
        deps = {}
        in_deps = False
        with open(self.toml_path, "r", encoding="utf-8") as f:
            for line in f:
                l = line.strip()
                if l.startswith("[dependencies]"):
                    in_deps = True
                    continue
                elif l.startswith("["):
                    in_deps = False
                    continue
                if in_deps and "=" in l:
                    k, v = l.split("=", 1)
                    deps[k.strip()] = v.strip().strip('"\'')
                elif not in_deps and "=" in l:
                    k, v = l.split("=", 1)
                    k = k.strip()
                    v = v.strip().strip('"\'')
                    if k == "name":
                        name = v
                    elif k == "version":
                        version = v
                    elif k == "target":
                        target = v
                    elif k == "description":
                        desc = v
        return ProjectManifest(name=name, version=version, target=target, description=desc, dependencies=deps)

    def save_manifest(self, manifest: ProjectManifest) -> None:
        lines = [
            "[project]",
            f'name = "{manifest.name}"',
            f'version = "{manifest.version}"',
            f'target = "{manifest.target}"',
            f'description = "{manifest.description}"',
            "",
            "[dependencies]"
        ]
        for k, v in manifest.dependencies.items():
            lines.append(f'{k} = "{v}"')
        lines.append("")
        with open(self.toml_path, "w", encoding="utf-8") as f:
            f.write("\n".join(lines))

    def _compute_checksum(self, dir_or_file: str) -> str:
        h = hashlib.sha256()
        if os.path.isfile(dir_or_file):
            with open(dir_or_file, "rb") as f:
                h.update(f.read())
        elif os.path.isdir(dir_or_file):
            for root, _, files in sorted(os.walk(dir_or_file)):
                for f in sorted(files):
                    fp = os.path.join(root, f)
                    with open(fp, "rb") as fh:
                        h.update(fh.read())
        return f"sha256:{h.hexdigest()}"

    def add_package(self, package_name: str, version: str = "0.1.0", local_path: Optional[str] = None) -> bool:
        if not os.path.exists(self.toml_path):
            raise FileNotFoundError(f"No star.toml found in '{self.project_dir}'. Run 'star init' first.")

        # Read existing star.toml
        with open(self.toml_path, "r", encoding="utf-8") as f:
            content = f.read()

        dep_line = f'{package_name} = "{version}"\n'
        if "[dependencies]" in content:
            parts = content.split("[dependencies]")
            new_content = parts[0] + "[dependencies]\n" + dep_line + parts[1].lstrip("\n")
        else:
            new_content = content.rstrip() + "\n\n[dependencies]\n" + dep_line

        with open(self.toml_path, "w", encoding="utf-8") as f:
            f.write(new_content)

        # Run install to lock
        self.install()
        return True

    def remove_package(self, package_name: str) -> bool:
        if not os.path.exists(self.toml_path):
            raise FileNotFoundError(f"No star.toml found in '{self.project_dir}'.")

        with open(self.toml_path, "r", encoding="utf-8") as f:
            lines = f.readlines()

        new_lines = [l for l in lines if not l.strip().startswith(package_name)]
        with open(self.toml_path, "w", encoding="utf-8") as f:
            f.writelines(new_lines)

        self.install()
        return True

    def install(self) -> Lockfile:
        os.makedirs(self.packages_dir, exist_ok=True)
        deps: List[Dependency] = []

        if os.path.exists(self.toml_path):
            with open(self.toml_path, "r", encoding="utf-8") as f:
                lines = f.readlines()

            in_deps = False
            for line in lines:
                l = line.strip()
                if l == "[dependencies]":
                    in_deps = True
                    continue
                elif l.startswith("["):
                    in_deps = False
                    continue

                if in_deps and "=" in l:
                    k, v = l.split("=", 1)
                    pkg_name = k.strip()
                    pkg_ver = v.strip().strip('"').strip("'")
                    pkg_path = os.path.join(self.packages_dir, pkg_name)
                    csum = self._compute_checksum(pkg_path) if os.path.exists(pkg_path) else "sha256:none"
                    deps.append(Dependency(name=pkg_name, version=pkg_ver, source=f"local:packages/{pkg_name}", checksum=csum))

        lock = Lockfile(version=1, packages=deps)
        with open(self.lock_path, "w", encoding="utf-8") as f:
            f.write(lock.to_toml())

        return lock

    def pack(self, out_path: Optional[str] = None) -> str:
        if not os.path.exists(self.toml_path):
            raise FileNotFoundError(f"No star.toml found in '{self.project_dir}'.")

        from star_engine.project import load_project
        cfg = load_project(self.project_dir)
        p_name = cfg.name if cfg else "package"
        p_ver = cfg.version if cfg else "0.1.0"

        target_file = out_path or os.path.join(self.project_dir, f"{p_name}-{p_ver}.starpkg")

        # Create gzip tarball
        with tarfile.open(target_file, "w:gz") as tar:
            if os.path.exists(self.toml_path):
                tar.add(self.toml_path, arcname="star.toml")
            src_dir = os.path.join(self.project_dir, "src")
            if os.path.exists(src_dir):
                tar.add(src_dir, arcname="src")
            main_star = os.path.join(self.project_dir, "main.star")
            if os.path.exists(main_star):
                tar.add(main_star, arcname="main.star")

        return target_file

    def verify_lockfile(self) -> Tuple[bool, List[str]]:
        if not os.path.exists(self.lock_path):
            return False, ["No star.lock found."]

        errors: List[str] = []
        with open(self.lock_path, "r", encoding="utf-8") as f:
            lines = f.readlines()

        curr_pkg = None
        curr_csum = None
        for line in lines:
            l = line.strip()
            if l.startswith('name = "'):
                curr_pkg = l.split('name = "')[1].rstrip('"')
            elif l.startswith('checksum = "'):
                curr_csum = l.split('checksum = "')[1].rstrip('"')
                if curr_pkg and curr_csum and curr_csum != "sha256:none":
                    pkg_path = os.path.join(self.packages_dir, curr_pkg)
                    if os.path.exists(pkg_path):
                        actual_csum = self._compute_checksum(pkg_path)
                        if actual_csum != curr_csum:
                            errors.append(f"Checksum mismatch for '{curr_pkg}': expected {curr_csum}, got {actual_csum}")
                curr_pkg = None
                curr_csum = None

        return len(errors) == 0, errors
